; divmod.asm - Integer division a / b by repeated subtraction (the SSEM has no
; hardware divider), producing both the quotient Q and the remainder R.
; Put the dividend a on line 30 and the divisor b on line 31 (b must be > 0);
; when the machine stops, the quotient is on line 28 and the remainder on line 29.
; For example 100 / 7 -> Q = 14, R = 2.
;
; This program was generated by AI (model: Mistral Large 4)
;
; Encoding notes:
; - Line 00 holds the constant ONE = 1: word 0 is usable as data because CI is
;   pre-incremented (execution starts at line 01) and no jump here lands on
;   CI = 31, so line 00 is never executed.
; - JRP is indirect: to land on line T from a JRP on line L, store[S] must be
;   T - L - 1. Lines 23, 24 and 25 are those jump-target words.
; - The remainder r is kept negated on line 27 (RN), so LDN 27 loads +r and
;   "r -= b" is LDN 27 / SUB 31, then negated back into RN through T (line 26).

00 NUM 1     ; ONE = 1 (constant; line 00 is never executed)
01 LDN 30    ; A = -a
02 STO 27    ;   RN = -a, i.e. r = a  (Q on line 28 starts at 0)
03 LDN 27    ; loop: A = r
04 SUB 31    ;   A = r - b
05 CMP       ;   skip next if r - b < 0, i.e. r < b (done)
06 JRP 24    ;   r >= b -> body (line 8)
07 JRP 25    ;   r < b -> done (line 19)
08 LDN 27    ; body: A = r
09 SUB 31    ;   A = r - b
10 STO 26    ;   T = r - b
11 LDN 26    ;   A = -(r - b)
12 STO 27    ;   r = r - b
13 LDN 28    ;   A = -Q
14 SUB 00    ;   A = -Q - 1 = -(Q + 1)
15 STO 26    ;   T = -(Q + 1)
16 LDN 26    ;   A = Q + 1
17 STO 28    ;   Q = Q + 1
18 JRP 23    ;   back to loop (line 3)
19 LDN 27    ; done: A = r
20 STO 29    ;   R = r (remainder)
21 STP       ;   Q (line 28) is the quotient
22 NUM 0     ;
23 NUM -16   ; jump word for line 18: 3 - 18 - 1
24 NUM 1     ; jump word for line 06: 8 - 6 - 1
25 NUM 11    ; jump word for line 07: 19 - 7 - 1
26 NUM 0     ; T: temp, used to negate the accumulator
27 NUM 0     ; RN: remainder r, stored negated (-r)
28 NUM 0     ; ---> Q: quotient (result)
29 NUM 0     ; ---> R: remainder (result)
30 NUM 100   ; <--- a: dividend (input)
31 NUM 7     ; <--- b: divisor (input, must be > 0)
